<style>
.prep-shell{font-size:14px;width:100%;box-sizing:border-box;padding:18px 20px 24px}.prep-hero{background:linear-gradient(120deg,#0b668f,#12aaa4);color:#fff;border-radius:16px;padding:20px 24px;margin-bottom:16px}.prep-grid{display:grid;grid-template-columns:minmax(280px,380px) minmax(0,1fr);gap:16px}.prep-card{min-width:0;background:#fff;border:1px solid #cfe3eb;border-radius:14px;padding:18px;box-shadow:0 8px 22px rgba(9,65,91,.08)}.prep-field{margin-bottom:14px}.prep-field label{display:block;font-weight:700;color:#174a65;margin-bottom:6px}.prep-field input{width:100%;border:1px solid #bed5df;border-radius:8px;padding:10px}.prep-btn{display:inline-flex;align-items:center;gap:6px;border:0;border-radius:8px;padding:9px 13px;font-weight:700;color:#fff;background:linear-gradient(120deg,#087eb5,#13aaa1);cursor:pointer}.prep-table{width:100%;border-collapse:collapse}.prep-table th,.prep-table td{padding:10px;border-bottom:1px solid #dce9ee;text-align:left}.prep-actions{display:flex;gap:6px;flex-wrap:wrap}.prep-actions .prep-btn{padding:7px 9px}.prep-muted{color:#79909d;font-size:12px}.prep-ok{color:#098443;font-weight:700}.prep-pending{color:#b56b00;font-weight:700}.prep-pagination{display:flex;justify-content:center;gap:5px;flex-wrap:wrap;margin-top:18px}.prep-page{border:1px solid #bed8e2;border-radius:7px;padding:8px 11px;color:#087aa6;background:#fff;font-weight:700}.prep-page:hover,.prep-page.active{color:#fff;background:linear-gradient(120deg,#087eb5,#13aaa1);text-decoration:none}.prep-page.disabled{pointer-events:none;color:#9aabb3;background:#edf3f5}.prep-loading{opacity:.45;pointer-events:none}.prep-notice{display:none;margin-bottom:12px}.prep-edit-form input{margin:3px;max-width:260px}@media(max-width:900px){.prep-shell{padding:12px}.prep-grid{grid-template-columns:1fr}.prep-table{display:block;overflow-x:auto}}
</style>
<style>
.prep-btn:disabled{cursor:not-allowed;filter:grayscale(.25);opacity:.55}.prep-upload{position:relative;display:flex!important;align-items:center;gap:12px;min-height:112px;padding:16px;border:2px dashed #a9cfdd!important;border-radius:12px;background:linear-gradient(145deg,#f8fcfd,#eef8fa);cursor:pointer;transition:border-color .18s,background .18s,transform .18s}.prep-upload:hover,.prep-upload.is-dragging{border-color:#0798ad!important;background:#e9f8fa;transform:translateY(-1px)}.prep-upload.has-file{border-style:solid!important;border-color:#66bea8!important;background:#effaf6}.prep-upload.has-error{border-color:#dc6674!important;background:#fff3f4}.prep-upload input{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0!important}.prep-upload-icon{display:grid;flex:0 0 48px;place-items:center;width:48px;height:48px;border-radius:12px;color:#fff;background:linear-gradient(145deg,#e84655,#b91f32);box-shadow:0 7px 16px rgba(185,31,50,.2);font-size:22px}.prep-upload-copy{min-width:0;flex:1}.prep-upload-copy strong,.prep-upload-copy span{display:block}.prep-upload-copy strong{margin-bottom:4px;color:#174a65}.prep-upload-copy span{color:#718995;font-size:12px;line-height:1.4}.prep-file-name{overflow:hidden;color:#087653!important;font-weight:700;text-overflow:ellipsis;white-space:nowrap}.prep-file-remove{display:none;flex:0 0 auto;width:30px;height:30px;border:0;border-radius:50%;color:#a63242;background:#ffe9ec;cursor:pointer}.prep-upload.has-file .prep-file-remove{display:inline-grid;place-items:center}.prep-upload-status{min-height:18px;margin-top:5px;font-size:11px}.prep-upload-status.is-error{color:#bd293d}.prep-upload-status.is-valid{color:#087653}
.prep-edit-form{padding:14px;border:1px solid #cfe2e9;border-radius:11px;background:#f8fbfc}.prep-edit-grid{display:grid;grid-template-columns:minmax(170px,1fr) minmax(230px,1.35fr) auto auto;align-items:end;gap:10px}.prep-edit-control label{display:block;margin-bottom:5px;color:#456574;font-size:11px;font-weight:700}.prep-edit-control>input{width:100%;max-width:none!important;margin:0!important;border:1px solid #bed5df;border-radius:8px;padding:9px}.prep-edit-upload{position:relative;display:flex;align-items:center;gap:9px;min-height:42px;margin:0;padding:7px 9px;border:1px dashed #91bfce;border-radius:9px;background:#fff;cursor:pointer}.prep-edit-upload:hover,.prep-edit-upload.is-dragging{border-color:#0798ad;background:#edf9fa}.prep-edit-upload.has-file{border-style:solid;border-color:#62b89f;background:#effaf6}.prep-edit-upload.has-error{border-color:#d75969;background:#fff2f3}.prep-edit-upload input{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;overflow:hidden;clip:rect(0,0,0,0);border:0!important}.prep-edit-upload-icon{display:grid;flex:0 0 30px;place-items:center;width:30px;height:30px;border-radius:8px;color:#c52f42;background:#ffe8eb}.prep-edit-upload-copy{min-width:0;flex:1}.prep-edit-upload-copy strong,.prep-edit-upload-copy span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.prep-edit-upload-copy strong{color:#174a65;font-size:11px}.prep-edit-upload-copy span{color:#718995;font-size:10px}.prep-edit-remove{display:none;width:25px;height:25px;border:0;border-radius:50%;color:#a63242;background:#ffe1e5;cursor:pointer}.prep-edit-upload.has-file .prep-edit-remove{display:inline-grid;place-items:center}.prep-edit-active{display:flex!important;align-items:center;gap:6px;margin:0 2px 10px!important;white-space:nowrap}.prep-edit-active input{width:auto!important;margin:0!important}.prep-edit-save{margin-bottom:1px;white-space:nowrap}@media(max-width:1100px){.prep-edit-grid{grid-template-columns:1fr 1fr}.prep-edit-save{width:100%}}@media(max-width:650px){.prep-edit-grid{grid-template-columns:1fr}}
</style>
<div class="prep-shell">
  <div class="prep-hero"><small>CONFIGURACIÓN CLÍNICA · V3</small><h2><i class="fas fa-file-pdf"></i> Preparaciones clínicas</h2><div>Administre por empresa los documentos PDF que se entregan al paciente.</div></div>
  <div id="prep-notice" class="prep-notice alert"></div>
  <div class="prep-grid">
    <section class="prep-card">
      <h4><i class="fas fa-plus-circle"></i> Nueva preparación</h4>
      <form id="prep-create-form" class="prep-ajax-form" method="post" novalidate action="{{ route('v3.preparations.store') }}" enctype="multipart/form-data">
        {{ csrf_field() }}
        <div class="prep-field"><label>Nombre de la preparación</label><input name="nombre_preparaciones" value="{{ old('nombre_preparaciones') }}" required maxlength="255"></div>
        <div class="prep-field">
          <label>Documento PDF</label>
          <label class="prep-upload" id="prep-upload" for="prep-file">
            <input id="prep-file" type="file" name="archivo" accept="application/pdf,.pdf" required>
            <span class="prep-upload-icon"><i class="fas fa-file-pdf"></i></span>
            <span class="prep-upload-copy"><strong id="prep-upload-title">Seleccionar documento</strong><span id="prep-upload-help">Haz clic o arrastra aquí un archivo PDF</span><span id="prep-file-name" class="prep-file-name" hidden></span></span>
            <button type="button" class="prep-file-remove" id="prep-file-remove" title="Quitar archivo" aria-label="Quitar archivo"><i class="fas fa-times"></i></button>
          </label>
          <div id="prep-upload-status" class="prep-upload-status">PDF · Tamaño máximo 15 MB</div>
        </div>
        <button id="prep-save" class="prep-btn" disabled><i class="fas fa-save"></i> Guardar preparación</button>
      </form>
    </section>
    <section class="prep-card">
      <div class="prep-field"><input id="prep-search" type="search" value="{{ $search }}" placeholder="Buscar preparación automáticamente..."></div>
      <div id="prep-table-area">@include('v3.clinical.preparations.partials.table')</div>
    </section>
  </div>
</div>
<script>
(function(){
  var area=document.getElementById('prep-table-area'), search=document.getElementById('prep-search'), notice=document.getElementById('prep-notice'), timer,
    upload=document.getElementById('prep-upload'), fileInput=document.getElementById('prep-file'), fileName=document.getElementById('prep-file-name'),
    uploadTitle=document.getElementById('prep-upload-title'), uploadHelp=document.getElementById('prep-upload-help'), uploadStatus=document.getElementById('prep-upload-status'),
    removeFile=document.getElementById('prep-file-remove'), saveButton=document.getElementById('prep-save'), selectedUploadFile=null;
  function message(text,error){notice.textContent=text;notice.className='prep-notice alert '+(error?'alert-danger':'alert-success');notice.style.display='block';}
  function formatBytes(bytes){if(bytes<1024)return bytes+' B';if(bytes<1048576)return (bytes/1024).toFixed(1)+' KB';return (bytes/1048576).toFixed(1)+' MB';}
  function resetUpload(){selectedUploadFile=null;fileInput.value='';upload.classList.remove('has-file','has-error','is-dragging');uploadTitle.textContent='Seleccionar documento';uploadHelp.hidden=false;fileName.hidden=true;fileName.textContent='';uploadStatus.textContent='PDF · Tamaño máximo 15 MB';uploadStatus.className='prep-upload-status';saveButton.disabled=true;}
  function showFile(file){var validType=file&&(file.type==='application/pdf'||/\.pdf$/i.test(file.name)),validSize=file&&file.size<=15*1024*1024;upload.classList.remove('has-file','has-error');if(!validType||!validSize){selectedUploadFile=null;upload.classList.add('has-error');uploadStatus.className='prep-upload-status is-error';uploadStatus.textContent=!validType?'Selecciona un documento en formato PDF.':'El documento supera el máximo permitido de 15 MB.';fileInput.value='';saveButton.disabled=true;return;}selectedUploadFile=file;upload.classList.add('has-file');uploadTitle.textContent='Documento listo para subir';uploadHelp.hidden=true;fileName.textContent=file.name+' · '+formatBytes(file.size);fileName.hidden=false;uploadStatus.textContent='Archivo válido y listo para guardar';uploadStatus.className='prep-upload-status is-valid';saveButton.disabled=false;}
  fileInput.addEventListener('change',function(){if(fileInput.files&&fileInput.files[0])showFile(fileInput.files[0]);else resetUpload();});
  ['dragenter','dragover'].forEach(function(type){upload.addEventListener(type,function(e){e.preventDefault();upload.classList.add('is-dragging');});});
  ['dragleave','drop'].forEach(function(type){upload.addEventListener(type,function(e){e.preventDefault();upload.classList.remove('is-dragging');});});
  upload.addEventListener('drop',function(e){if(!e.dataTransfer||!e.dataTransfer.files.length)return;try{fileInput.files=e.dataTransfer.files;}catch(ignore){}showFile(e.dataTransfer.files[0]);});
  removeFile.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();resetUpload();});
  function listUrl(page){return window.location.pathname+'?buscar='+encodeURIComponent(search.value)+'&page='+(page||1);}
  function load(url){area.classList.add('prep-loading');fetch(url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}}).then(function(r){if(!r.ok)return r.text().then(function(body){throw new Error('HTTP '+r.status+' '+body.substring(0,120));});return r.text();}).then(function(html){area.innerHTML=html;area.classList.remove('prep-loading');history.replaceState(null,'',url);notice.style.display='none';}).catch(function(error){area.classList.remove('prep-loading');message('No se pudo cambiar de página. Inténtalo nuevamente.',true);if(window.console)console.error('Preparaciones:',error);});}
  search.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(function(){load(listUrl(1));},300);});
  area.addEventListener('click',function(e){var remove=e.target.closest('.prep-edit-remove');if(remove){e.preventDefault();e.stopPropagation();resetEditUpload(remove.closest('.prep-edit-upload'));return;}var page=e.target.closest('.prep-page:not(.disabled)');if(page){e.preventDefault();load(listUrl(parseInt(page.getAttribute('data-page'),10)||1));return;}var edit=e.target.closest('.prep-edit-open');if(edit){var form=document.getElementById(edit.getAttribute('data-target'));if(form)form.style.display=form.style.display==='none'?'block':'none';}});
  function resetEditUpload(wrapper){if(!wrapper)return;var input=wrapper.querySelector('.prep-edit-file'),copy=wrapper.querySelector('.prep-edit-file-copy');input.value='';input._selectedFile=null;wrapper.classList.remove('has-file','has-error','is-dragging');copy.textContent='Seleccionar un nuevo PDF';}
  function showEditFile(wrapper,file){if(!wrapper||!file)return;var input=wrapper.querySelector('.prep-edit-file'),copy=wrapper.querySelector('.prep-edit-file-copy'),validType=file.type==='application/pdf'||/\.pdf$/i.test(file.name),validSize=file.size<=15*1024*1024;wrapper.classList.remove('has-file','has-error');if(!validType||!validSize){input.value='';input._selectedFile=null;wrapper.classList.add('has-error');copy.textContent=!validType?'El archivo debe ser PDF':'Supera el máximo de 15 MB';return;}input._selectedFile=file;wrapper.classList.add('has-file');copy.textContent=file.name+' · '+formatBytes(file.size);}
  area.addEventListener('change',function(e){if(!e.target.matches('.prep-edit-file'))return;var wrapper=e.target.closest('.prep-edit-upload');if(e.target.files&&e.target.files[0])showEditFile(wrapper,e.target.files[0]);else resetEditUpload(wrapper);});
  area.addEventListener('dragover',function(e){var wrapper=e.target.closest('.prep-edit-upload');if(!wrapper)return;e.preventDefault();wrapper.classList.add('is-dragging');});
  area.addEventListener('dragleave',function(e){var wrapper=e.target.closest('.prep-edit-upload');if(wrapper)wrapper.classList.remove('is-dragging');});
  area.addEventListener('drop',function(e){var wrapper=e.target.closest('.prep-edit-upload');if(!wrapper)return;e.preventDefault();wrapper.classList.remove('is-dragging');if(!e.dataTransfer||!e.dataTransfer.files.length)return;var input=wrapper.querySelector('.prep-edit-file');try{input.files=e.dataTransfer.files;}catch(ignore){}showEditFile(wrapper,e.dataTransfer.files[0]);});
  document.addEventListener('submit',function(e){var form=e.target;if(!form.classList.contains('prep-ajax-form'))return;e.preventDefault();var data=new FormData(form),editFile=form.querySelector('.prep-edit-file');if(form.id==='prep-create-form'&&selectedUploadFile)data.set('archivo',selectedUploadFile,selectedUploadFile.name);if(editFile&&editFile._selectedFile)data.set('archivo',editFile._selectedFile,editFile._selectedFile.name);data.set('buscar',search.value);form.classList.add('prep-loading');fetch(form.action,{method:form.method||'POST',body:data,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.json().then(function(j){if(!r.ok)throw j;return j;});}).then(function(j){area.innerHTML=j.html;message(j.message,false);if(form.id==='prep-create-form'){form.reset();resetUpload();}}).catch(function(j){var errors=j&&j.errors?Object.keys(j.errors).map(function(k){return j.errors[k].join(' ');}).join(' '):'No se pudo guardar la preparación.';message(errors,true);}).then(function(){form.classList.remove('prep-loading');});
  });
  resetUpload();
})();
</script>
